function drawSolgaleoSunLion(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.0;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 34 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(14, by + 12); ctx.lineTo(32, by - 6); ctx.lineTo(22, by + 18); ctx.fill();
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.arc(32, by - 6, 4, 0, Math.PI * 2); ctx.fill();

  // 3. Thân
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(-2, by + 12, 16 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. 4 Chân
  [-16, -8, 4, 12].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 6, 18, 2); ctx.fill();
    ctx.fillStyle = '#f97316';
    ctx.fillRect(x, by + 30, 6, 3);
    ctx.fillStyle = '#ffffff';
  });

  // 5. Bờm Thái Dương
  ctx.beginPath();
  ctx.moveTo(-10, by - 12); ctx.lineTo(-34, by - 32); ctx.lineTo(-18, by - 24);
  ctx.moveTo(-10, by - 12); ctx.lineTo(-8,  by - 42); ctx.lineTo(0,   by - 26);
  ctx.moveTo(0,   by - 12); ctx.lineTo(8,   by - 42); ctx.lineTo(10,  by - 26);
  ctx.moveTo(10,  by - 12); ctx.lineTo(34,  by - 32); ctx.lineTo(18,  by - 24);
  ctx.moveTo(-10, by - 6);  ctx.lineTo(-36, by - 4);  ctx.lineTo(-20, by + 4);
  ctx.moveTo(10,  by - 6);  ctx.lineTo(36,  by - 4);  ctx.lineTo(20,  by + 4);
  ctx.fill();

  // Chóp cam
  ctx.fillStyle = '#f97316';
  [[-30, -28], [-6, -38], [6, -38], [30, -28]].forEach(pt => {
    ctx.beginPath(); ctx.arc(pt[0], by + pt[1], 3, 0, Math.PI * 2); ctx.fill();
  });

  // 6. Ngôi sao 4 cánh vàng
  ctx.strokeStyle = '#facc15'; ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(-14, by - 10); ctx.lineTo(14, by - 10);
  ctx.moveTo(0,   by - 24); ctx.lineTo(0,  by + 4);
  ctx.stroke();

  // 7. Mặt nạ ngân hà
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.arc(0, by - 10, 8, 0, Math.PI * 2); ctx.fill();

  // 8. Mắt xanh
  if (!blink) {
    ctx.fillStyle = '#06b6d4';
    ctx.beginPath(); ctx.arc(-3, by - 10, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,  by - 10, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-3, by - 11, 0.8, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,  by - 11, 0.8, 0, Math.PI * 2); ctx.fill();
  }

  ctx.restore();
}
